{"content":"import { useRef, useEffect } from 'react';
import { useSphere } from '@react-three/cannon';
import type { BallId, Vec3Tuple } from '../types';
import { BALL_RADIUS, HALF_WIDTH, HALF_LENGTH, POCKET_POSITIONS, POCKET_RADIUS } from '../constants/table';
import {
  BALL_MASS,
  LINEAR_DAMPING,
  ANGULAR_DAMPING,
  BALL_BALL_FRICTION,
  BALL_BALL_RESTITUTION,
} from '../constants/physics';
import { useGameStore } from '../store/gameStore';
import { distance } from '../utils/vector';
import { generateBallTexture } from '../utils/textures';
import { registerBallApi, unregisterBallApi } from '../hooks/useShotSequence';
import * as THREE from 'three';
import { useMemo } from 'react';

interface BallBodyProps {
  id: BallId;
  initialPosition: Vec3Tuple;
}

export default function BallBody({ id, initialPosition }: BallBodyProps) {
  const meshRef = useRef<THREE.Mesh>(null);
  const pocketedRef = useRef(false);

  const texture = useMemo(() => {
    const canvas = generateBallTexture(id);
    const tex = new THREE.CanvasTexture(canvas);
    tex.colorSpace = THREE.SRGBColorSpace;
    return tex;
  }, [id]);

  const [ref, api] = useSphere<THREE.Mesh>(() => ({
    mass: BALL_MASS,
    position: initialPosition,
    args: [BALL_RADIUS],
    material: {
      friction: BALL_BALL_FRICTION,
      restitution: BALL_BALL_RESTITUTION,
    },
    linearDamping: LINEAR_DAMPING,
    angularDamping: ANGULAR_DAMPING,
  }));

  // Register ball API for shot sequence impulse application
  useEffect(() => {
    registerBallApi(id, api as any);
    return () => unregisterBallApi(id);
  }, [api, id]);

  // Subscribe to position for pocket detection and cue ball tracking
  useEffect(() => {
    const unsub = api.position.subscribe((pos: [number, number, number]) => {
      if (meshRef.current) {
        meshRef.current.position.set(pos[0], pos[1], pos[2]);
      }

      // Track cue ball position
      if (id === 0) {
        useGameStore.getState().setCueBallPosition(pos);
      }

      // Pocket detection during simulation
      const { phase } = useGameStore.getState();
      if (phase === 'SIMULATING' && !pocketedRef.current) {
        for (const pocketPos of POCKET_POSITIONS) {
          const dist = distance(pos, pocketPos);
          if (dist < POCKET_RADIUS) {
            pocketedRef.current = true;
            useGameStore.getState().pocketBall(id);
            // Drop ball below table
            api.position.set(pos[0], -0.5, pos[2]);
            api.velocity.set(0, 0, 0);
            api.angularVelocity.set(0, 0, 0);
            break;
          }
        }
      }
    });
    return unsub;
  }, [api, id]);

  return (
    <mesh ref={meshRef} position={initialPosition} castShadow receiveShadow>
      <sphereGeometry args={[BALL_RADIUS, 32, 32]} />
      <meshStandardMaterial
        map={texture}
        roughness={0.15}
        metalness={0.05}
      />
    </mesh>
  );
}","end_line":94,"start_line":0,"total_lines":95}

{"content":"import type { BallId, Vec3Tuple } from '../types';
import { POCKET_POSITIONS, POCKET_RADIUS } from '../constants/table';
import { vec3Distance } from '../utils/vector';

/**
 * Check if any balls are within pocket zones
 * Returns list of ball IDs that should be pocketed
 */
export function detectPocketedBalls(
  ballPositions: Record<number, Vec3Tuple>,
  alreadyPocketed: Set<number>
): BallId[] {
  const pocketed: BallId[] = [];

  for (const [idStr, pos] of Object.entries(ballPositions)) {
    const id = Number(idStr) as BallId;
    if (alreadyPocketed.has(id)) continue;

    for (const pocketPos of POCKET_POSITIONS) {
      const dist = vec3Distance(pos, pocketPos);
      if (dist < POCKET_RADIUS) {
        pocketed.push(id);
        break;
      }
    }
  }

  return pocketed;
}

/**
 * Check if a single position is within any pocket zone
 */
export function isInPocket(pos: Vec3Tuple): boolean {
  for (const pocketPos of POCKET_POSITIONS) {
    const dist = vec3Distance(pos, pocketPos);
    if (dist < POCKET_RADIUS) return true;
  }
  return false;
}","end_line":39,"start_line":0,"total_lines":40}

{"content":"import { Canvas } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import Table from './Table';
import Balls from './Balls';
import CueStick from './CueStick';
import AimLine from './AimLine';
import PhysicsWorld from '../physics/PhysicsWorld';
import useSettleDetector from '../hooks/useSettleDetector';
import useShotSequence from '../hooks/useShotSequence';
import {
  CAMERA_DEFAULT_POSITION,
  CAMERA_FOV,
  HALF_LENGTH,
  HALF_WIDTH,
} from '../constants/table';

/**
 * Wrapper for game hooks that must run inside the Canvas/Physics context.
 */
function GameHooks() {
  useSettleDetector();
  useShotSequence();
  return null;
}

/**
 * R3F Canvas with shadow map, perspective camera (45 deg FOV) positioned above
 * the table at an angle, ambient + directional + point lights, and
 * OrbitControls constrained so the user cannot go below the table.
 */
export default function Scene() {
  const orbitTarget: [number, number, number] = [0, 0, 0];

  return (
    <Canvas
      shadows
      camera={{
        position: CAMERA_DEFAULT_POSITION,
        fov: CAMERA_FOV,
        near: 0.01,
        far: 50,
      }}
      style={{ width: '100%', height: '100%' }}
    >
      <color attach="background" args={['#1a1a2e']} />

      {/* Lighting */}
      <ambientLight intensity={0.35} color="#ffffff" />
      <directionalLight
        position={[0, 3, 0.5]}
        intensity={1.2}
        color="#fffbe6"
        castShadow
        shadow-mapSize-width={2048}
        shadow-mapSize-height={2048}
        shadow-camera-far={10}
        shadow-camera-left={-HALF_WIDTH - 0.3}
        shadow-camera-right={HALF_WIDTH + 0.3}
        shadow-camera-top={HALF_LENGTH + 0.3}
        shadow-camera-bottom={-HALF_LENGTH - 0.3}
        shadow-bias={-0.0005}
      />
      <pointLight
        position={[-HALF_WIDTH * 0.4, 1.5, -HALF_LENGTH * 0.6]}
        intensity={0.5}
        color="#fff5e6"
        distance={5}
        decay={2}
      />
      <pointLight
        position={[HALF_WIDTH * 0.4, 1.5, HALF_LENGTH * 0.6]}
        intensity={0.5}
        color="#fff5e6"
        distance={5}
        decay={2}
      />

      {/* Physics world wrapping all game objects */}
      <PhysicsWorld>
        <Table />
        <Balls />
        <CueStick />
        <AimLine />
        <GameHooks />
      </PhysicsWorld>

      {/* Camera controls */}
      <OrbitControls
        target={orbitTarget}
        enablePan={false}
        enableDamping
        dampingFactor={0.08}
        minPolarAngle={0.2}
        maxPolarAngle={Math.PI / 2.15}
        minDistance={0.8}
        maxDistance={4.5}
      />

      {/* Floor plane */}
      <mesh
        rotation={[-Math.PI / 2, 0, 0]}
        position={[0, -0.82, 0]}
        receiveShadow
      >
        <planeGeometry args={[20, 20]} />
        <meshStandardMaterial color="#0e0806" />
      </mesh>

      <fog attach="fog" args={['#1a1a2e', 6, 14]} />
    </Canvas>
  );
}","end_line":111,"start_line":0,"total_lines":112}

{"content":"import { useRef, useMemo } from 'react';
import * as THREE from 'three';
import type { BallId } from '../types';
import { BALL_RADIUS } from '../constants/table';
import { generateBallTexture } from '../utils/textures';

export interface BallProps {
  id: BallId;
  position: [number, number, number];
}

/**
 * A single billiard ball rendered as a sphere with a procedural canvas texture.
 *
 * The texture is generated once per `id` and cached via `useMemo`.
 * The sphere uses the standard BALL_RADIUS constant and a
 * physically-motivated material (low roughness, tiny metalness).
 */
export default function Ball({ id, position: initialPos }: BallProps) {
  const meshRef = useRef<THREE.Mesh>(null);

  const texture = useMemo(() => {
    const canvas = generateBallTexture(id);
    const tex = new THREE.CanvasTexture(canvas);
    tex.colorSpace = THREE.SRGBColorSpace;
    return tex;
  }, [id]);

  return (
    <mesh
      ref={meshRef}
      position={initialPos}
      castShadow
      receiveShadow
    >
      <sphereGeometry args={[BALL_RADIUS, 32, 32]} />
      <meshStandardMaterial
        map={texture}
        roughness={0.15}
        metalness={0.05}
      />
    </mesh>
  );
}","end_line":43,"start_line":0,"total_lines":44}

{"content":"import { useMemo } from 'react';
import { ALL_BALL_IDS } from '../types';
import type { BallId } from '../types';
import { getRackPositions } from '../constants/balls';
import Ball from './Ball';

/**
 * Container component that renders all 16 balls at their initial positions.
 * Maps ball IDs 0–15, rendering a <Ball> for each at INITIAL_POSITIONS.
 */
export default function Balls() {
  const initialPositions = useMemo(() => getRackPositions(), []);

  return (
    <group>
      {ALL_BALL_IDS.map((id: BallId) => (
        <Ball
          key={id}
          id={id}
          position={initialPositions[id]}
        />
      ))}
    </group>
  );
}","end_line":24,"start_line":0,"total_lines":25}

{"content":"import { useMemo } from 'react';
import * as THREE from 'three';
import {
  TABLE_LENGTH,
  TABLE_WIDTH,
  RAIL_HEIGHT,
  RAIL_WIDTH,
  HALF_LENGTH,
  HALF_WIDTH,
  POCKET_POSITIONS,
  POCKET_RADIUS,
  CUSHION_THICKNESS,
  CUSHION_HEIGHT,
  BALL_RADIUS,
} from '../constants/table';
import { generateFeltTexture, generateWoodTexture } from '../utils/textures';

export default function Table() {
  const feltTexture = useMemo(() => {
    const canvas = generateFeltTexture();
    const tex = new THREE.CanvasTexture(canvas);
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(4, 8);
    return tex;
  }, []);

  const woodTexture = useMemo(() => {
    const canvas = generateWoodTexture();
    const tex = new THREE.CanvasTexture(canvas);
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    return tex;
  }, []);

  // Long rail half-length (between side-pocket gap and corner-pocket gap)
  const longSegmentLength = HALF_LENGTH - RAIL_WIDTH * 1.2;
  // Short rail full length
  const shortRailLength = TABLE_WIDTH;

  return (
    <group>
      {/* ── Table Bed (green felt surface) ── */}
      <mesh position={[0, -0.005, 0]} receiveShadow>
        <boxGeometry args={[TABLE_WIDTH, 0.01, TABLE_LENGTH]} />
        <meshStandardMaterial color="#0d6b2e" map={feltTexture} roughness={0.9} />
      </mesh>

      {/* ── Wooden frame beneath bed ── */}
      <mesh position={[0, -0.025, 0]} receiveShadow>
        <boxGeometry
          args={[
            TABLE_WIDTH + RAIL_WIDTH * 2,
            0.03,
            TABLE_LENGTH + RAIL_WIDTH * 2,
          ]}
        />
        <meshStandardMaterial color="#3b1f0b" map={woodTexture} roughness={0.7} />
      </mesh>

      {/* ── Wooden Rails ── */}

      {/* Left rail – two segments (gap at middle for side pocket) */}
      <RailSegment
        position={[
          -HALF_WIDTH - RAIL_WIDTH / 2,
          RAIL_HEIGHT / 2,
          -HALF_LENGTH / 2 - RAIL_WIDTH / 4,
        ]}
        size={[RAIL_WIDTH, RAIL_HEIGHT, longSegmentLength]}
        texture={woodTexture}
      />
      <RailSegment
        position={[
          -HALF_WIDTH - RAIL_WIDTH / 2,
          RAIL_HEIGHT / 2,
          HALF_LENGTH / 2 + RAIL_WIDTH / 4,
        ]}
        size={[RAIL_WIDTH, RAIL_HEIGHT, longSegmentLength]}
        texture={woodTexture}
      />

      {/* Right rail – two segments (gap at middle for side pocket) */}
      <RailSegment
        position={[
          HALF_WIDTH + RAIL_WIDTH / 2,
          RAIL_HEIGHT / 2,
          -HALF_LENGTH / 2 - RAIL_WIDTH / 4,
        ]}
        size={[RAIL_WIDTH, RAIL_HEIGHT, longSegmentLength]}
        texture={woodTexture}
      />
      <RailSegment
        position={[
          HALF_WIDTH + RAIL_WIDTH / 2,
          RAIL_HEIGHT / 2,
          HALF_LENGTH / 2 + RAIL_WIDTH / 4,
        ]}
        size={[RAIL_WIDTH, RAIL_HEIGHT, longSegmentLength]}
        texture={woodTexture}
      />

      {/* Head rail (near end, Z negative) */}
      <RailSegment
        position={[0, RAIL_HEIGHT / 2, -HALF_LENGTH - RAIL_WIDTH / 2]}
        size={[shortRailLength, RAIL_HEIGHT, RAIL_WIDTH]}
        texture={woodTexture}
      />

      {/* Foot rail (far end, Z positive) */}
      <RailSegment
        position={[0, RAIL_HEIGHT / 2, HALF_LENGTH + RAIL_WIDTH / 2]}
        size={[shortRailLength, RAIL_HEIGHT, RAIL_WIDTH]}
        texture={woodTexture}
      />

      {/* ── Cushions (green rubber bumpers, slightly angled inward) ── */}

      {/* Head-end left cushion */}
      <CushionSegment
        position={[
          -HALF_WIDTH / 2 - RAIL_WIDTH * 0.3,
          CUSHION_HEIGHT / 2,
          -HALF_LENGTH + CUSHION_THICKNESS / 2 + 0.005,
        ]}
        size={[HALF_WIDTH - RAIL_WIDTH * 1.4, CUSHION_HEIGHT, CUSHION_THICKNESS]}
      />

      {/* Head-end right cushion */}
      <CushionSegment
        position={[
          HALF_WIDTH / 2 + RAIL_WIDTH * 0.3,
          CUSHION_HEIGHT / 2,
          -HALF_LENGTH + CUSHION_THICKNESS / 2 + 0.005,
        ]}
        size={[HALF_WIDTH - RAIL_WIDTH * 1.4, CUSHION_HEIGHT, CUSHION_THICKNESS]}
      />

      {/* Foot-end left cushion */}
      <CushionSegment
        position={[
          -HALF_WIDTH / 2 - RAIL_WIDTH * 0.3,
          CUSHION_HEIGHT / 2,
          HALF_LENGTH - CUSHION_THICKNESS / 2 - 0.005,
        ]}
        size={[HALF_WIDTH - RAIL_WIDTH * 1.4, CUSHION_HEIGHT, CUSHION_THICKNESS]}
      />

      {/* Foot-end right cushion */}
      <CushionSegment
        position={[
          HALF_WIDTH / 2 + RAIL_WIDTH * 0.3,
          CUSHION_HEIGHT / 2,
          HALF_LENGTH - CUSHION_THICKNESS / 2 - 0.005,
        ]}
        size={[HALF_WIDTH - RAIL_WIDTH * 1.4, CUSHION_HEIGHT, CUSHION_THICKNESS]}
      />

      {/* Left side cushion */}
      <CushionSegment
        position={[
          -HALF_WIDTH + CUSHION_THICKNESS / 2 + 0.005,
          CUSHION_HEIGHT / 2,
          0,
        ]}
        size={[
          CUSHION_THICKNESS,
          CUSHION_HEIGHT,
          TABLE_LENGTH - RAIL_WIDTH * 3,
        ]}
      />

      {/* Right side cushion */}
      <CushionSegment
        position={[
          HALF_WIDTH - CUSHION_THICKNESS / 2 - 0.005,
          CUSHION_HEIGHT / 2,
          0,
        ]}
        size={[
          CUSHION_THICKNESS,
          CUSHION_HEIGHT,
          TABLE_LENGTH - RAIL_WIDTH * 3,
        ]}
      />

      {/* ── Pockets (6 dark circles) ── */}
      {POCKET_POSITIONS.map((pos, i) => (
        <group key={i} position={[pos[0], 0.001, pos[2]]}>
          {/* Pocket hole */}
          <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <circleGeometry args={[POCKET_RADIUS, 32]} />
            <meshStandardMaterial color="#050505" roughness={1} />
          </mesh>
          {/* Pocket rim */}
          <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <ringGeometry args={[POCKET_RADIUS, POCKET_RADIUS + 0.006, 32]} />
            <meshStandardMaterial color="#2a1506" roughness={0.6} />
          </mesh>
        </group>
      ))}
    </group>
  );
}

/* ────────────────────────────────────────────────────────────────────────────
   Sub-components
   ──────────────────────────────────────────────────────────────────────────── */

function RailSegment({
  position,
  size,
  texture,
}: {
  position: [number, number, number];
  size: [number, number, number];
  texture: THREE.Texture;
}) {
  return (
    <mesh position={position} castShadow receiveShadow>
      <boxGeometry args={size} />
      <meshStandardMaterial map={texture} color="#5C3317" roughness={0.65} />
    </mesh>
  );
}

function CushionSegment({
  position,
  size,
}: {
  position: [number, number, number];
  size: [number, number, number];
}) {
  return (
    <mesh position={position}>
      <boxGeometry args={size} />
      <meshStandardMaterial color="#0a8a3a" roughness={0.85} />
    </mesh>
  );
}","end_line":237,"start_line":0,"total_lines":238}

