{"content":"import { create } from 'zustand';
import type { GamePhase, Player, BallGroup, BallId, FoulType, Vec3Tuple, ShotSnapshot } from '../types';
import { getRackPositions } from '../constants/balls';

interface GameStoreState {
  // Game phase state machine
  phase: GamePhase;

  // Current turn
  currentPlayer: Player;

  // Group assignment: which group each player has
  playerGroups: Record<Player, BallGroup>;

  // Balls pocketed this game
  pocketedBalls: BallId[];

  // Balls pocketed during current shot
  ballsPocketedThisShot: BallId[];

  // Current foul
  foul: FoulType;

  // Winner
  winner: Player | null;

  // Ball-in-hand after foul
  ballInHand: boolean;
  ballInHandPosition: Vec3Tuple | null;

  // Cue ball position (tracked by physics subscription)
  cueBallPosition: Vec3Tuple;

  // Shot history for undo (max 1 step)
  shotHistory: ShotSnapshot[];

  // First ball contacted by cue ball this shot
  firstContact: BallId | null;
}

interface GameStoreActions {
  // Phase transitions
  startAiming: () => void;
  startPower: () => void;
  shoot: () => void;
  setSimulating: () => void;
  evaluateShot: () => void;
  nextTurn: () => void;
  setGameOver: (winner: Player) => void;
  resetGame: () => void;

  // Ball tracking
  pocketBall: (id: BallId) => void;
  setFirstContact: (id: BallId) => void;
  setCueBallPosition: (pos: Vec3Tuple) => void;

  // Ball-in-hand
  setBallInHand: (enabled: boolean) => void;
  placeBallInHand: (pos: Vec3Tuple) => void;

  // Snapshot for undo
  takeSnapshot: () => void;
  undo: () => ShotSnapshot | null;

  // Evaluation helpers
  setFoul: (foul: FoulType) => void;
  assignGroups: (player: Player, group: BallGroup) => void;
}

export type GameStore = GameStoreState & GameStoreActions;

const initialPositions = getRackPositions();

export const useGameStore = create<GameStore>((set, get) => ({
  // Initial state
  phase: 'IDLE',
  currentPlayer: 1,
  playerGroups: { 1: null, 2: null },
  pocketedBalls: [],
  ballsPocketedThisShot: [],
  foul: null,
  winner: null,
  ballInHand: false,
  ballInHandPosition: null,
  cueBallPosition: initialPositions[0],
  shotHistory: [],
  firstContact: null,

  // Phase transitions
  startAiming: () => {
    const { phase, ballInHand } = get();
    if (phase === 'IDLE' && !ballInHand) {
      set({ phase: 'AIMING' });
    }
  },

  startPower: () => {
    const { phase } = get();
    if (phase === 'AIMING') {
      set({ phase: 'POWER' });
    }
  },

  shoot: () => {
    const { phase } = get();
    if (phase === 'POWER') {
      // Clear shot-specific tracking
      set({
        phase: 'SIMULATING',
        ballsPocketedThisShot: [],
        firstContact: null,
        foul: null,
      });
    }
  },

  setSimulating: () => {
    set({ phase: 'SIMULATING' });
  },

  evaluateShot: () => {
    const { phase } = get();
    if (phase === 'SIMULATING') {
      set({ phase: 'EVALUATING' });
    }
  },

  nextTurn: () => {
    const { currentPlayer } = get();
    set({
      phase: 'IDLE',
      currentPlayer: currentPlayer === 1 ? 2 : 1,
      ballsPocketedThisShot: [],
      firstContact: null,
    });
  },

  setGameOver: (winner: Player) => {
    set({ phase: 'GAME_OVER', winner });
  },

  resetGame: () => {
    const positions = getRackPositions();
    set({
      phase: 'IDLE',
      currentPlayer: 1,
      playerGroups: { 1: null, 2: null },
      pocketedBalls: [],
      ballsPocketedThisShot: [],
      foul: null,
      winner: null,
      ballInHand: false,
      ballInHandPosition: null,
      cueBallPosition: positions[0],
      shotHistory: [],
      firstContact: null,
    });
  },

  // Ball tracking
  pocketBall: (id: BallId) => {
    const { pocketedBalls, ballsPocketedThisShot } = get();
    if (!pocketedBalls.includes(id)) {
      set({
        pocketedBalls: [...pocketedBalls, id],
        ballsPocketedThisShot: [...ballsPocketedThisShot, id],
      });
    }
  },

  setFirstContact: (id: BallId) => {
    const { firstContact } = get();
    if (firstContact === null) {
      set({ firstContact: id });
    }
  },

  setCueBallPosition: (pos: Vec3Tuple) => {
    set({ cueBallPosition: pos });
  },

  // Ball-in-hand
  setBallInHand: (enabled: boolean) => {
    set({ ballInHand: enabled, phase: enabled ? 'IDLE' : get().phase });
  },

  placeBallInHand: (pos: Vec3Tuple) => {
    set({
      ballInHand: false,
      ballInHandPosition: pos,
      cueBallPosition: pos,
    });
  },

  // Snapshot for undo
  takeSnapshot: () => {
    const state = get();
    const snapshot: ShotSnapshot = {
      ballPositions: {}, // Will be populated by caller with actual physics positions
      state: {
        currentPlayer: state.currentPlayer,
        playerGroups: { ...state.playerGroups },
        pocketedBalls: [...state.pocketedBalls],
      },
    };
    set({ shotHistory: [snapshot] }); // Keep only 1 step
  },

  undo: () => {
    const { shotHistory } = get();
    if (shotHistory.length === 0) return null;
    return shotHistory[0];
  },

  // Evaluation helpers
  setFoul: (foul: FoulType) => {
    set({ foul });
  },

  assignGroups: (player: Player, group: BallGroup) => {
    const otherPlayer: Player = player === 1 ? 2 : 1;
    const otherGroup: BallGroup = group === 'solids' ? 'stripes' : 'solids';
    set({
      playerGroups: {
        [player]: group,
        [otherPlayer]: otherGroup,
      } as Record<Player, BallGroup>,
    });
  },
}));","end_line":229,"start_line":0,"total_lines":230}

{"content":"import { create } from 'zustand';
import type { Vec3Tuple } from '../types';

interface AimStoreState {
  direction: Vec3Tuple;
  power: number;
  isCharging: boolean;
  cameraMode: 'orbit' | 'topdown';
}

interface AimStoreActions {
  setDirection: (dir: Vec3Tuple) => void;
  setPower: (power: number) => void;
  startCharging: () => void;
  stopCharging: () => void;
  resetPower: () => void;
  toggleCameraMode: () => void;
  setCameraMode: (mode: 'orbit' | 'topdown') => void;
}

export const useAimStore = create<AimStoreState & AimStoreActions>((set) => ({
  direction: [0, 0, 1],
  power: 0,
  isCharging: false,
  cameraMode: 'orbit',

  setDirection: (dir: Vec3Tuple) => set({ direction: dir }),
  setPower: (power: number) => set({ power: Math.min(1, Math.max(0, power)) }),
  startCharging: () => set({ isCharging: true, power: 0 }),
  stopCharging: () => set({ isCharging: false }),
  resetPower: () => set({ power: 0, isCharging: false }),
  toggleCameraMode: () =>
    set((s) => ({ cameraMode: s.cameraMode === 'orbit' ? 'topdown' : 'orbit' })),
  setCameraMode: (mode) => set({ cameraMode: mode }),
}));","end_line":34,"start_line":0,"total_lines":35}

{"content":"import { useEffect, useRef } from 'react';
import { useGameStore } from '../store/gameStore';
import { useAimStore } from '../store/aimStore';
import { evaluateShot } from '../game-logic/rules';
import { MAX_IMPULSE } from '../constants/physics';

// We'll store ball API references here for physics impulse application
const ballApis: Map<number, { applyImpulse: (impulse: [number, number, number]) => void }> = new Map();

export function registerBallApi(id: number, api: { applyImpulse: (impulse: [number, number, number]) => void }) {
  ballApis.set(id, api);
}

export function unregisterBallApi(id: number) {
  ballApis.delete(id);
}

/**
 * Hook that orchestrates the full shot sequence:
 * 1. Apply impulse to cue ball
 * 2. Wait for settle
 * 3. Evaluate shot result
 * 4. Transition to next phase
 */
export default function useShotSequence() {
  const settleTimerRef = useRef(0);
  const settleFramesRef = useRef(0);

  useEffect(() => {
    let intervalId: ReturnType<typeof setInterval>;

    const checkSettle = () => {
      const { phase, ballsPocketedThisShot, firstContact, currentPlayer, playerGroups, cueBallPosition, pocketedBalls } = useGameStore.getState();

      if (phase === 'SIMULATING') {
        settleTimerRef.current++;

        // After a minimum simulation time (~2 seconds), start checking settle
        if (settleTimerRef.current > 120) {
          settleFramesRef.current++;

          // Check if settled (after ~1.5 additional seconds)
          if (settleFramesRef.current > 90 || settleTimerRef.current > 360) {
            settleTimerRef.current = 0;
            settleFramesRef.current = 0;

            // Transition to EVALUATING
            useGameStore.getState().evaluateShot();

            // Evaluate shot result
            const state = useGameStore.getState();
            const isBreak = state.pocketedBalls.length === 0 && state.shotHistory.length === 0;

            const result = evaluateShot(
              state.currentPlayer,
              state.playerGroups,
              state.ballsPocketedThisShot,
              state.firstContact,
              state.cueBallPosition,
              isBreak
            );

            // Apply results
            if (result.foul) {
              useGameStore.getState().setFoul(result.foul);
            }

            if (result.assignGroup) {
              useGameStore.getState().assignGroups(
                result.assignGroup.player,
                result.assignGroup.group
              );
            }

            if (result.gameOver) {
              useGameStore.getState().setGameOver(result.winner!);
            } else {
              if (result.ballInHand) {
                useGameStore.getState().setBallInHand(true);
              }
              // Reset for next turn
              const nextPhase = result.ballInHand ? 'IDLE' : 'IDLE';
              useGameStore.setState({
                phase: nextPhase,
                currentPlayer: result.nextPlayer,
                ballsPocketedThisShot: [],
                firstContact: null,
              });
            }

            // Reset aim
            useAimStore.getState().resetPower();
          }
        }
      } else {
        settleTimerRef.current = 0;
        settleFramesRef.current = 0;
      }
    };

    intervalId = setInterval(checkSettle, 16); // ~60fps

    return () => clearInterval(intervalId);
  }, []);

  // Handle shot trigger
  useEffect(() => {
    const handleMouseDown = (e: MouseEvent) => {
      const { phase } = useGameStore.getState();
      if (phase === 'IDLE') {
        useGameStore.getState().startAiming();
      } else if (phase === 'AIMING') {
        useGameStore.getState().startPower();
        useAimStore.getState().startCharging();
      }
    };

    const handleMouseUp = (e: MouseEvent) => {
      const { phase } = useGameStore.getState();
      const { power, direction, isCharging } = useAimStore.getState();

      if (phase === 'POWER' && isCharging) {
        // Take snapshot for undo
        useGameStore.getState().takeSnapshot();

        // Apply impulse to cue ball
        const impulseMagnitude = power * MAX_IMPULSE;
        const impulse: [number, number, number] = [
          direction[0] * impulseMagnitude,
          0,
          direction[2] * impulseMagnitude,
        ];

        const cueApi = ballApis.get(0);
        if (cueApi) {
          cueApi.applyImpulse(impulse);
        }

        // Transition to SIMULATING
        useGameStore.getState().shoot();
        useAimStore.getState().stopCharging();
      }
    };

    const handleMouseMove = (e: MouseEvent) => {
      const { phase } = useGameStore.getState();
      if (phase === 'AIMING' || phase === 'IDLE') {
        // Compute aim direction from mouse
        const rect = document.querySelector('canvas')?.getBoundingClientRect();
        if (!rect) return;

        const ndcX = ((e.clientX - rect.left) / rect.width) * 2 - 1;
        const ndcY = -((e.clientY - rect.top) / rect.height) * 2 + 1;

        // Simple aim calculation: map mouse X position to aim angle
        const angle = ndcX * Math.PI;
        const aimDir: [number, number, number] = [
          Math.sin(angle),
          0,
          Math.cos(angle),
        ];
        useAimStore.getState().setDirection(aimDir);
      }
    };

    // Handle ball-in-hand placement
    const handleClick = (e: MouseEvent) => {
      const { ballInHand, phase } = useGameStore.getState();
      if (ballInHand && phase === 'IDLE') {
        const rect = document.querySelector('canvas')?.getBoundingClientRect();
        if (!rect) return;

        const ndcX = ((e.clientX - rect.left) / rect.width) * 2 - 1;
        const ndcY = -((e.clientY - rect.top) / rect.height) * 2 + 1;

        // Map to table coordinates
        const x = ndcX * 0.5;
        const z = -ndcY * 1.0;

        useGameStore.getState().placeBallInHand([x, 0.0285, z]);
      }
    };

    // Undo key
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'u' || e.key === 'U') {
        const snapshot = useGameStore.getState().undo();
        if (snapshot) {
          useGameStore.setState({
            currentPlayer: snapshot.state.currentPlayer,
            playerGroups: snapshot.state.playerGroups,
            pocketedBalls: snapshot.state.pocketedBalls,
          });
        }
      }
      // Top-down camera toggle
      if (e.key === 't' || e.key === 'T') {
        useAimStore.getState().toggleCameraMode();
      }
    };

    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('keydown', handleKeyDown);

    return () => {
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, []);
}","end_line":213,"start_line":0,"total_lines":214}

{"content":"import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { useGameStore } from '../store/gameStore';
import { SETTLE_FRAMES } from '../constants/physics';

/**
 * Hook that detects when all balls have settled (stopped moving).
 * Must be used inside a Canvas component.
 */
export default function useSettleDetector() {
  const settleCountRef = useRef(0);

  useFrame(() => {
    const { phase, evaluateShot } = useGameStore.getState();

    if (phase !== 'SIMULATING') {
      settleCountRef.current = 0;
      return;
    }

    // In a real implementation, we'd check all ball velocities here.
    // For now, we use a timer-based approach since physics bodies
    // track their own velocities. The settle check is handled by
    // the shot sequence hook monitoring physics state.

    // This is a fallback: after enough frames in SIMULATING,
    // trigger evaluation. The real settle detection would check
    // each ball body's velocity via the physics API subscriptions.
    settleCountRef.current++;

    if (settleCountRef.current >= 180) {
      // ~3 seconds at 60fps as a safety fallback
      settleCountRef.current = 0;
      evaluateShot();
    }
  });
}","end_line":36,"start_line":0,"total_lines":37}

{"content":"import { useCallback } from 'react';
import { useThree } from '@react-three/fiber';
import * as THREE from 'three';
import { useAimStore } from '../store/aimStore';
import { useGameStore } from '../store/gameStore';
import { normalize, sub } from '../utils/vector';

/**
 * Hook that computes aim direction from mouse position.
 * Must be used inside a Canvas component.
 */
export default function useAim() {
  const { camera, gl } = useThree();
  const raycaster = new THREE.Raycaster();
  const tablePlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);

  const computeAim = useCallback(
    (mouseX: number, mouseY: number) => {
      const { phase, cueBallPosition } = useGameStore.getState();
      if (phase !== 'AIMING' && phase !== 'POWER' && phase !== 'IDLE') return;

      // Normalize mouse coords to [-1, 1]
      const rect = gl.domElement.getBoundingClientRect();
      const ndcX = ((mouseX - rect.left) / rect.width) * 2 - 1;
      const ndcY = -((mouseY - rect.top) / rect.height) * 2 + 1;

      raycaster.setFromCamera(new THREE.Vector2(ndcX, ndcY), camera);

      const intersection = new THREE.Vector3();
      raycaster.ray.intersectPlane(tablePlane, intersection);

      if (intersection) {
        const hitPoint: [number, number, number] = [intersection.x, 0, intersection.z];
        const direction = sub(hitPoint, cueBallPosition);
        // Only use XZ direction (keep it on the table plane)
        const aimDir = normalize([direction[0], 0, direction[2]]);
        useAimStore.getState().setDirection(aimDir);
      }
    },
    [camera, gl]
  );

  return { computeAim };
}","end_line":43,"start_line":0,"total_lines":44}

{"content":"import { useEffect, useRef } from 'react';
import { useAimStore } from '../store/aimStore';
import { useGameStore } from '../store/gameStore';
import { POWER_CHARGE_RATE } from '../constants/physics';

/**
 * Hook that manages power charging during the POWER phase.
 */
export default function usePower() {
  const frameRef = useRef<number>(0);
  const lastTimeRef = useRef<number>(0);

  useEffect(() => {
    let running = true;

    const animate = (time: number) => {
      if (!running) return;

      const { isCharging, power } = useAimStore.getState();
      const { phase } = useGameStore.getState();

      if (isCharging && phase === 'POWER') {
        const delta = lastTimeRef.current ? (time - lastTimeRef.current) / 1000 : 0;
        const newPower = Math.min(1, power + delta * POWER_CHARGE_RATE);
        useAimStore.getState().setPower(newPower);
      }

      lastTimeRef.current = time;
      frameRef.current = requestAnimationFrame(animate);
    };

    frameRef.current = requestAnimationFrame(animate);

    return () => {
      running = false;
      cancelAnimationFrame(frameRef.current);
    };
  }, []);
}","end_line":38,"start_line":0,"total_lines":39}

{"content":"/**
 * 3D vector utilities operating on [x, y, z] tuples.
 *
 * These pure functions avoid allocating class instances and are
 * compatible with Three.js, cannon-es, and our own constants.
 */
export type Vec3Tuple = [number, number, number];

// ---------------------------------------------------------------------------
// Creation / conversion helpers
// ---------------------------------------------------------------------------

/** Create a Vec3Tuple from individual components. */
export function vec3(x: number, y: number, z: number): Vec3Tuple {
  return [x, y, z];
}

/** Zero vector constant (immutable – treat as read-only). */
export const VEC3_ZERO: Readonly<Vec3Tuple> = [0, 0, 0];

/** Unit vectors along each axis. */
export const VEC3_UP: Readonly<Vec3Tuple> = [0, 1, 0];
export const VEC3_RIGHT: Readonly<Vec3Tuple> = [1, 0, 0];
export const VEC3_FORWARD: Readonly<Vec3Tuple> = [0, 0, 1];

// ---------------------------------------------------------------------------
// Basic operations
// ---------------------------------------------------------------------------

/** Euclidean distance between two points. */
export function distance(a: Vec3Tuple, b: Vec3Tuple): number {
  const dx = a[0] - b[0];
  const dy = a[1] - b[1];
  const dz = a[2] - b[2];
  return Math.sqrt(dx * dx + dy * dy + dz * dz);
}

/** Squared distance (avoids the sqrt when only comparisons are needed). */
export function distanceSq(a: Vec3Tuple, b: Vec3Tuple): number {
  const dx = a[0] - b[0];
  const dy = a[1] - b[1];
  const dz = a[2] - b[2];
  return dx * dx + dy * dy + dz * dz;
}

/** Length (magnitude) of a vector. */
export function length(v: Vec3Tuple): number {
  return Math.sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
}

/** Squared length. */
export function lengthSq(v: Vec3Tuple): number {
  return v[0] * v[0] + v[1] * v[1] + v[2] * v[2];
}

/** Return the unit-length copy of `v`. Returns [0,0,0] for zero-length input. */
export function normalize(v: Vec3Tuple): Vec3Tuple {
  const len = Math.sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
  if (len === 0) return [0, 0, 0];
  return [v[0] / len, v[1] / len, v[2] / len];
}

/** Component-wise subtraction: a − b. */
export function sub(a: Vec3Tuple, b: Vec3Tuple): Vec3Tuple {
  return [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
}

/** Component-wise addition: a + b. */
export function add(a: Vec3Tuple, b: Vec3Tuple): Vec3Tuple {
  return [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
}

/** Scalar multiplication. */
export function scale(v: Vec3Tuple, s: number): Vec3Tuple {
  return [v[0] * s, v[1] * s, v[2] * s];
}

/** Negate a vector. */
export function negate(v: Vec3Tuple): Vec3Tuple {
  return [-v[0], -v[1], -v[2]];
}

/** Component-wise multiplication (Hadamard product). */
export function multiply(a: Vec3Tuple, b: Vec3Tuple): Vec3Tuple {
  return [a[0] * b[0], a[1] * b[1], a[2] * b[2]];
}

// ---------------------------------------------------------------------------
// Interpolation / reflection
// ---------------------------------------------------------------------------

/** Linear interpolation between `a` and `b` by factor `t` ∈ [0, 1]. */
export function lerp(a: Vec3Tuple, b: Vec3Tuple, t: number): Vec3Tuple {
  return [
    a[0] + (b[0] - a[0]) * t,
    a[1] + (b[1] - a[1]) * t,
    a[2] + (b[2] - a[2]) * t,
  ];
}

/**
 * Reflect vector `v` about `normal`.
 * Assumes `normal` is unit-length.
 */
export function reflect(v: Vec3Tuple, normal: Vec3Tuple): Vec3Tuple {
  const d = dot(v, normal);
  return [
    v[0] - 2 * d * normal[0],
    v[1] - 2 * d * normal[1],
    v[2] - 2 * d * normal[2],
  ];
}

// ---------------------------------------------------------------------------
// Products
// ---------------------------------------------------------------------------

/** Dot product. */
export function dot(a: Vec3Tuple, b: Vec3Tuple): number {
  return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
}

/** Cross product. */
export function cross(a: Vec3Tuple, b: Vec3Tuple): Vec3Tuple {
  return [
    a[1] * b[2] - a[2] * b[1],
    a[2] * b[0] - a[0] * b[2],
    a[0] * b[1] - a[1] * b[0],
  ];
}

/** Angle in radians between two vectors. Returns 0 if either is zero-length. */
export function angle(a: Vec3Tuple, b: Vec3Tuple): number {
  const lenA = Math.sqrt(a[0] * a[0] + a[1] * a[1] + a[2] * a[2]);
  const lenB = Math.sqrt(b[0] * b[0] + b[1] * b[1] + b[2] * b[2]);
  if (lenA === 0 || lenB === 0) return 0;
  const cosAngle = Math.max(-1, Math.min(1, dot(a, b) / (lenA * lenB)));
  return Math.acos(cosAngle);
}

// ---------------------------------------------------------------------------
// Utility
// ---------------------------------------------------------------------------

/** Check strict equality of two vectors. */
export function equals(a: Vec3Tuple, b: Vec3Tuple): boolean {
  return a[0] === b[0] && a[1] === b[1] && a[2] === b[2];
}

/** Check approximate equality within an epsilon. */
export function approxEquals(a: Vec3Tuple, b: Vec3Tuple, eps = 1e-6): boolean {
  return (
    Math.abs(a[0] - b[0]) < eps &&
    Math.abs(a[1] - b[1]) < eps &&
    Math.abs(a[2] - b[2]) < eps
  );
}

/**
 * Clamp each component of `v` to the range [min, max].
 */
export function clamp(v: Vec3Tuple, min: number, max: number): Vec3Tuple {
  return [
    Math.max(min, Math.min(max, v[0])),
    Math.max(min, Math.min(max, v[1])),
    Math.max(min, Math.min(max, v[2])),
  ];
}

/**
 * Project vector `a` onto vector `b`.
 */
export function project(a: Vec3Tuple, b: Vec3Tuple): Vec3Tuple {
  const lenSqB = lengthSq(b);
  if (lenSqB === 0) return [0, 0, 0];
  const scalar = dot(a, b) / lenSqB;
  return scale(b, scalar);
}

// ─────────────────────────────────────────────────────────────────────────────
// Backwards-compatible aliases (old naming convention)
// ─────────────────────────────────────────────────────────────────────────────
/** @deprecated Use {@link distance} */
export const vec3Distance = distance;
/** @deprecated Use {@link normalize} */
export const vec3Normalize = normalize;
/** @deprecated Use {@link sub} */
export const vec3Sub = sub;
/** @deprecated Use {@link add} */
export const vec3Add = add;
/** @deprecated Use {@link scale} */
export const vec3Scale = scale;
/** @deprecated Use {@link lerp} */
export const vec3Lerp = lerp;
/** @deprecated Use {@link reflect} */
export const vec3Reflect = reflect;
/** @deprecated Use {@link dot} */
export const vec3Dot = dot;
/** @deprecated Use {@link cross} */
export const vec3Cross = cross;
/** @deprecated Use {@link angle} */
export const vec3Angle = angle;
/** @deprecated Use {@link length} */
export const vec3Length = length;

/**
 * Returns a string representation for debugging.
 */
export function toString(v: Vec3Tuple, precision = 4): string {
  return `(${v[0].toFixed(precision)}, ${v[1].toFixed(precision)}, ${v[2].toFixed(precision)})`;
