{"content":"import type { BallId } from '../types';
import { BALL_COLORS } from '../constants/balls';
import { isStripe } from '../types';

const TEXTURE_WIDTH = 512;
const TEXTURE_HEIGHT = 256;

/**
 * Generate a procedural canvas texture for a billiard ball (T09).
 *
 * - Cue ball (id 0): plain white
 * - Solid balls (1-7): solid color fill + white number circle
 * - Stripe balls (9-15): white background + colored band middle 50% + white number circle
 * - Eight ball (8): solid black + white number circle
 */
export function generateBallTexture(id: BallId): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = TEXTURE_WIDTH;
  canvas.height = TEXTURE_HEIGHT;
  const ctx = canvas.getContext('2d')!;

  if (id === 0) {
    // Cue ball: plain white
    ctx.fillStyle = '#F8F8FF';
    ctx.fillRect(0, 0, TEXTURE_WIDTH, TEXTURE_HEIGHT);
    // Subtle gloss highlight baked into texture
    const gloss = ctx.createRadialGradient(
      TEXTURE_WIDTH * 0.35, TEXTURE_HEIGHT * 0.35, 0,
      TEXTURE_WIDTH * 0.35, TEXTURE_HEIGHT * 0.35, TEXTURE_WIDTH * 0.3,
    );
    gloss.addColorStop(0, 'rgba(255, 255, 255, 0.3)');
    gloss.addColorStop(1, 'rgba(255, 255, 255, 0)');
    ctx.fillStyle = gloss;
    ctx.fillRect(0, 0, TEXTURE_WIDTH, TEXTURE_HEIGHT);
    return canvas;
  }

  const color = BALL_COLORS[id];
  const stripe = isStripe(id);

  if (stripe) {
    // Stripe ball: white background with colored band in middle 50%
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, TEXTURE_WIDTH, TEXTURE_HEIGHT);

    // Color band covering middle 50% of UV height
    const bandTop = TEXTURE_HEIGHT * 0.25;
    const bandBottom = TEXTURE_HEIGHT * 0.75;
    ctx.fillStyle = color;
    ctx.fillRect(0, bandTop, TEXTURE_WIDTH, bandBottom - bandTop);
  } else {
    // Solid ball: entire surface is the ball color
    ctx.fillStyle = color;
    ctx.fillRect(0, 0, TEXTURE_WIDTH, TEXTURE_HEIGHT);
  }

  // Number circle (white circle with black number)
  const cx = TEXTURE_WIDTH / 2;
  const cy = TEXTURE_HEIGHT / 2;
  const circleRadius = 30;

  ctx.beginPath();
  ctx.arc(cx, cy, circleRadius, 0, Math.PI * 2);
  ctx.fillStyle = '#FFFFFF';
  ctx.fill();
  ctx.strokeStyle = '#333333';
  ctx.lineWidth = 1;
  ctx.stroke();

  // Number text
  ctx.fillStyle = '#000000';
  ctx.font = 'bold 28px Arial, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(String(id), cx, cy + 1);

  return canvas;
}

/**
 * Generate a felt texture for the table bed.
 * Dark green base with subtle noise grain.
 */
export function generateFeltTexture(): HTMLCanvasElement {
  const size = 512;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d')!;

  // Base green
  ctx.fillStyle = '#0d6b2e';
  ctx.fillRect(0, 0, size, size);

  // Add noise grain for felt-like appearance
  const imageData = ctx.getImageData(0, 0, size, size);
  const data = imageData.data;
  for (let i = 0; i < data.length; i += 4) {
    const noise = (Math.random() - 0.5) * 15;
    data[i] = Math.max(0, Math.min(255, data[i] + noise));
    data[i + 1] = Math.max(0, Math.min(255, data[i + 1] + noise));
    data[i + 2] = Math.max(0, Math.min(255, data[i + 2] + noise));
  }
  ctx.putImageData(imageData, 0, 0);

  return canvas;
}

/**
 * Generate a wood grain texture for the rails.
 * Brown base with darker grain lines.
 */
export function generateWoodTexture(): HTMLCanvasElement {
  const size = 256;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d')!;

  // Base brown
  ctx.fillStyle = '#5C3317';
  ctx.fillRect(0, 0, size, size);

  // Wood grain lines
  ctx.strokeStyle = 'rgba(0, 0, 0, 0.15)';
  ctx.lineWidth = 1;
  for (let y = 0; y < size; y += 3 + Math.random() * 4) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    let x = 0;
    while (x < size) {
      x += 10 + Math.random() * 20;
      ctx.lineTo(x, y + (Math.random() - 0.5) * 2);
    }
    ctx.stroke();
  }

  return canvas;
}","end_line":138,"start_line":0,"total_lines":139}

{"content":"import type { BallId, Player, BallGroup, FoulType, Vec3Tuple } from '../types';
import { getBallGroup, EIGHT } from '../types';
import { HALF_WIDTH, HALF_LENGTH } from '../constants/table';

export interface EvaluationResult {
  foul: FoulType;
  nextPlayer: Player;
  gameOver: boolean;
  winner: Player | null;
  assignGroup: { player: Player; group: BallGroup } | null;
  ballInHand: boolean;
}

/**
 * Evaluate the result of a shot according to 8-ball rules.
 */
export function evaluateShot(
  currentPlayer: Player,
  playerGroups: Record<Player, BallGroup>,
  pocketedThisShot: BallId[],
  firstContact: BallId | null,
  cueBallPosition: Vec3Tuple,
  isBreak: boolean
): EvaluationResult {
  const myGroup = playerGroups[currentPlayer];
  let foul: FoulType = null;
  let ballInHand = false;

  // 1. Check for scratch (cue ball pocketed)
  const cueBallPocketed = pocketedThisShot.includes(0);
  if (cueBallPocketed) {
    foul = 'SCRATCH';
    ballInHand = true;
  }

  // 2. Check for no ball hit
  if (!cueBallPocketed && firstContact === null) {
    foul = 'NO_BALL_HIT';
    ballInHand = true;
  }

  // 3. Check wrong ball first contact (only if groups assigned)
  if (!cueBallPocketed && firstContact !== null && myGroup !== null) {
    const contactedGroup = getBallGroup(firstContact);
    if (contactedGroup !== myGroup) {
      foul = 'WRONG_BALL_FIRST';
      ballInHand = true;
    }
  }

  // 4. Check 8-ball pocketed
  const eightBallPocketed = pocketedThisShot.includes(EIGHT);

  // 5. Group assignment on first legal pocket
  let assignGroup: { player: Player; group: BallGroup } | null = null;
  const legalPockets = pocketedThisShot.filter((id) => id !== 0 && id !== EIGHT);

  if (myGroup === null && legalPockets.length > 0 && foul === null) {
    const firstPocketed = legalPockets[0];
    const group = getBallGroup(firstPocketed);
    if (group !== null) {
      assignGroup = { player: currentPlayer, group };
    }
  }

  // 6. Game over conditions
  if (eightBallPocketed) {
    // Check if 8-ball was pocketed legally
    const effectiveGroup = assignGroup ? assignGroup.group : myGroup;
    const allMyBallsPocketed = areAllGroupBallsPocketed(
      effectiveGroup,
      pocketedThisShot // We'd need the full list, simplified here
    );

    if (foul !== null || !allMyBallsPocketed || effectiveGroup === null) {
      // Illegal 8-ball pocket: current player loses
      const opponent: Player = currentPlayer === 1 ? 2 : 1;
      return {
        foul: foul || 'EIGHT_EARLY',
        nextPlayer: opponent,
        gameOver: true,
        winner: opponent,
        assignGroup,
        ballInHand: false,
      };
    } else {
      // Legal 8-ball pocket: current player wins
      return {
        foul: null,
        nextPlayer: currentPlayer,
        gameOver: true,
        winner: currentPlayer,
        assignGroup,
        ballInHand: false,
      };
    }
  }

  // 7. Determine if player keeps turn
  const playerKeepsTurn =
    foul === null && legalPockets.length > 0 &&
    (myGroup === null || legalPockets.some((id) => getBallGroup(id) === myGroup));

  return {
    foul,
    nextPlayer: playerKeepsTurn ? currentPlayer : (currentPlayer === 1 ? 2 : 1),
    gameOver: false,
    winner: null,
    assignGroup,
    ballInHand,
  };
}

/**
 * Check if all balls of a given group have been pocketed.
 * This is a simplified check - in practice would need all pocketed balls.
 */
function areAllGroupBallsPocketed(
  group: BallGroup,
  pocketed: BallId[]
): boolean {
  if (group === null) return false;

  const groupBalls = group === 'solids'
    ? [1, 2, 3, 4, 5, 6, 7] as BallId[]
    : [9, 10, 11, 12, 13, 14, 15] as BallId[];

  return groupBalls.every((id) => pocketed.includes(id));
}

/**
 * Check if position is within table bounds
 */
export function isWithinBounds(pos: Vec3Tuple): boolean {
  return (
    Math.abs(pos[0]) < HALF_WIDTH - 0.03 &&
    Math.abs(pos[2]) < HALF_LENGTH - 0.03
  );
}","end_line":138,"start_line":0,"total_lines":139}

{"content":"import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { useAimStore } from '../store/aimStore';
import { useGameStore } from '../store/gameStore';
import { add, scale } from '../utils/vector';
import { BALL_RADIUS } from '../constants/table';

const LINE_LENGTH = 2.0;

export default function AimLine() {
  const groupRef = useRef<THREE.Group>(null);
  const lineRef = useRef<THREE.LineSegments>(null);
  const ghostRef = useRef<THREE.Mesh>(null);

  useFrame(() => {
    if (!groupRef.current || !ghostRef.current) return;

    const { phase } = useGameStore.getState();
    const { direction } = useAimStore.getState();

    if (phase !== 'AIMING' && phase !== 'POWER' && phase !== 'IDLE') {
      groupRef.current.visible = false;
      return;
    }

    groupRef.current.visible = true;

    const { cueBallPosition } = useGameStore.getState();
    const endPoint = add(cueBallPosition, scale(direction, LINE_LENGTH));

    // Update line geometry
    if (lineRef.current) {
      const positions = lineRef.current.geometry.attributes.position as THREE.BufferAttribute;
      if (positions) {
        positions.setXYZ(0, cueBallPosition[0], 0.01, cueBallPosition[2]);
        positions.setXYZ(1, endPoint[0], 0.01, endPoint[2]);
        positions.needsUpdate = true;
      }
    }

    // Ghost ball at projected contact point
    ghostRef.current.visible = phase === 'AIMING';
    if (phase === 'AIMING') {
      const ghostPos = add(cueBallPosition, scale(direction, 0.5));
      ghostRef.current.position.set(ghostPos[0], BALL_RADIUS, ghostPos[2]);
    }
  });

  // Create a simple line geometry with 2 points
  const geometry = new THREE.BufferGeometry();
  const positions = new Float32Array(6); // 2 points * 3 components
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));

  return (
    <group ref={groupRef}>
      <lineSegments ref={lineRef} geometry={geometry}>
        <lineBasicMaterial color="#ffffff" opacity={0.5} transparent />
      </lineSegments>
      <mesh ref={ghostRef} visible={false}>
        <sphereGeometry args={[BALL_RADIUS, 16, 16]} />
        <meshStandardMaterial color="#ffffff" opacity={0.2} transparent />
      </mesh>
    </group>
  );
}","end_line":65,"start_line":0,"total_lines":66}

{"content":"import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { useAimStore } from '../store/aimStore';
import { useGameStore } from '../store/gameStore';
import { BALL_RADIUS } from '../constants/table';
import { sub, scale } from '../utils/vector';

const CUE_LENGTH = 1.4;
const CUE_RADIUS = 0.008;

export default function CueStick() {
  const meshRef = useRef<THREE.Group>(null);

  useFrame(() => {
    if (!meshRef.current) return;

    const { phase } = useGameStore.getState();
    const { direction, power } = useAimStore.getState();

    if (phase === 'SIMULATING' || phase === 'EVALUATING' || phase === 'GAME_OVER') {
      meshRef.current.visible = false;
      return;
    }

    meshRef.current.visible = true;

    const { cueBallPosition } = useGameStore.getState();

    // Position cue behind the ball, opposite to aim direction
    const backOffset = BALL_RADIUS + 0.05 + (phase === 'POWER' ? power * 0.3 : 0);
    const behindBall = sub(
      cueBallPosition,
      scale(direction, backOffset)
    );

    meshRef.current.position.set(behindBall[0], cueBallPosition[1], behindBall[2]);

    // Rotate to align with aim direction
    const angle = Math.atan2(direction[0], direction[2]);
    meshRef.current.rotation.set(0, angle, 0);

    // Strike animation: after POWER, briefly move forward
    if (phase === 'IDLE' || phase === 'AIMING') {
      // Default position
      const stickCenter = sub(
        cueBallPosition,
        scale(direction, backOffset + CUE_LENGTH / 2)
      );
      meshRef.current.position.set(stickCenter[0], cueBallPosition[1], stickCenter[2]);
    }
  });

  return (
    <group ref={meshRef}>
      {/* Cue stick shaft */}
      <mesh castShadow>
        <cylinderGeometry args={[CUE_RADIUS, CUE_RADIUS * 1.5, CUE_LENGTH, 8]} />
        <meshStandardMaterial color="#8B4513" roughness={0.4} />
      </mesh>
      {/* Cue tip */}
      <mesh position={[0, CUE_LENGTH / 2, 0]}>
        <cylinderGeometry args={[CUE_RADIUS * 0.8, CUE_RADIUS, 0.02, 8]} />
        <meshStandardMaterial color="#4169E1" roughness={0.6} />
      </mesh>
    </group>
  );
}","end_line":66,"start_line":0,"total_lines":67}

{"content":"import { useEffect, useState } from 'react';
import { useGameStore } from '../store/gameStore';
import { useAimStore } from '../store/aimStore';
import { BALL_COLORS } from '../constants/balls';
import { getBallGroup } from '../types';
import type { BallId, Player } from '../types';
import PowerMeter from './PowerMeter';

export default function GameUI() {
  const phase = useGameStore((s) => s.phase);
  const currentPlayer = useGameStore((s) => s.currentPlayer);
  const playerGroups = useGameStore((s) => s.playerGroups);
  const pocketedBalls = useGameStore((s) => s.pocketedBalls);
  const foul = useGameStore((s) => s.foul);
  const winner = useGameStore((s) => s.winner);
  const ballInHand = useGameStore((s) => s.ballInHand);

  const [foulToast, setFoulToast] = useState<string | null>(null);

  useEffect(() => {
    if (foul) {
      const messages: Record<string, string> = {
        SCRATCH: 'Scratch! Cue ball pocketed.',
        NO_BALL_HIT: 'Foul! No ball contacted.',
        WRONG_BALL_FIRST: 'Foul! Wrong ball hit first.',
        NO_RAIL_CONTACT: 'Foul! No rail after contact.',
        EIGHT_EARLY: 'Foul! 8-ball pocketed too early.',
      };
      setFoulToast(messages[foul] || `Foul: ${foul}`);
      const timer = setTimeout(() => setFoulToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [foul]);

  const handlePlayAgain = () => {
    useGameStore.getState().resetGame();
    useAimStore.getState().resetPower();
  };

  const player1Balls = pocketedBalls.filter((id) => {
    const group = playerGroups[1];
    if (!group) return false;
    return getBallGroup(id) === group;
  });

  const player2Balls = pocketedBalls.filter((id) => {
    const group = playerGroups[2];
    if (!group) return false;
    return getBallGroup(id) === group;
  });

  return (
    <>
      <PowerMeter />

      {/* Player indicators */}
      <div
        style={{
          position: 'fixed',
          top: '16px',
          left: '50%',
          transform: 'translateX(-50%)',
          display: 'flex',
          gap: '40px',
          fontFamily: 'system-ui, sans-serif',
          zIndex: 10,
        }}
      >
        <PlayerIndicator
          player={1}
          isCurrent={currentPlayer === 1}
          group={playerGroups[1]}
          pocketedBalls={player1Balls}
        />
        <PlayerIndicator
          player={2}
          isCurrent={currentPlayer === 2}
          group={playerGroups[2]}
          pocketedBalls={player2Balls}
        />
      </div>

      {/* Phase indicator */}
      <div
        style={{
          position: 'fixed',
          top: '80px',
          left: '50%',
          transform: 'translateX(-50%)',
          color: '#888',
          fontFamily: 'system-ui, sans-serif',
          fontSize: '12px',
          zIndex: 10,
        }}
      >
        {phase}
      </div>

      {/* Foul toast */}
      {foulToast && (
        <div
          style={{
            position: 'fixed',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            background: 'rgba(220, 38, 38, 0.9)',
            color: 'white',
            padding: '16px 32px',
            borderRadius: '8px',
            fontFamily: 'system-ui, sans-serif',
            fontSize: '18px',
            fontWeight: 'bold',
            zIndex: 20,
            animation: 'fadeIn 0.3s',
          }}
        >
          {foulToast}
        </div>
      )}

      {/* Ball-in-hand hint */}
      {ballInHand && (
        <div
          style={{
            position: 'fixed',
            bottom: '80px',
            left: '50%',
            transform: 'translateX(-50%)',
            color: '#eab308',
            fontFamily: 'system-ui, sans-serif',
            fontSize: '16px',
            zIndex: 10,
          }}
        >
          Click on the table to place the cue ball
        </div>
      )}

      {/* Controls hint */}
      <div
        style={{
          position: 'fixed',
          bottom: '16px',
          right: '16px',
          color: '#666',
          fontFamily: 'system-ui, sans-serif',
          fontSize: '11px',
          zIndex: 10,
        }}
      >
        <div>Click: Aim | Hold: Power | T: Top-down view | U: Undo</div>
      </div>

      {/* Game over modal */}
      {phase === 'GAME_OVER' && winner && (
        <div
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0, 0, 0, 0.7)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 30,
          }}
        >
          <div
            style={{
              background: '#1e293b',
              padding: '40px 60px',
              borderRadius: '16px',
              textAlign: 'center',
              fontFamily: 'system-ui, sans-serif',
              color: 'white',
            }}
          >
            <h2 style={{ fontSize: '32px', margin: '0 0 16px' }}>
              Player {winner} Wins!
            </h2>
            <button
              onClick={handlePlayAgain}
              style={{
                background: '#3b82f6',
                color: 'white',
                border: 'none',
                padding: '12px 32px',
                borderRadius: '8px',
                fontSize: '18px',
                cursor: 'pointer',
              }}
            >
              Play Again
            </button>
          </div>
        </div>
      )}
    </>
  );
}

function PlayerIndicator({
  player,
  isCurrent,
  group,
  pocketedBalls,
}: {
  player: Player;
  isCurrent: boolean;
  group: string | null;
  pocketedBalls: BallId[];
